import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './editarMascota.css'; // Importá el CSS

const EditarMascotaPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [mascota, setMascota] = useState(null);

  useEffect(() => {
    const fetchMascota = async () => {
      const res = await fetch(`http://localhost:3000/api/pets/${id}`);
      const data = await res.json();
      setMascota(data);
    };
    fetchMascota();
  }, [id]);

  const handleChange = (e) => {
    setMascota({ ...mascota, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    await fetch(`http://localhost:3000/api/pets/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(mascota),
    });
    navigate('/mis-mascotas'); // Volver a la lista después de guardar
  };

  if (!mascota) return <p>Cargando...</p>;

  return (
    <div className="editar-mascota-container">
      <h1>Editar reporte de mascota</h1>
      <form onSubmit={handleSubmit} className="form-editar">
        <label>Nombre</label>
        <input 
          name="name" 
          value={mascota.name} 
          onChange={handleChange} 
          required 
        />

        <label>Foto</label>
        <img src={mascota.imageUrl} alt={mascota.name} className="mascota-image" />
        <button type="button" className="btn-modificar-foto">Modificar foto</button>

        <label>Ubicación</label>
        <input 
          name="location" 
          value={mascota.location} 
          onChange={handleChange} 
          required 
        />

        <button type="submit" className="btn-guardar">Guardar</button>
        <button type="button" className="btn-reportar-encontrado">Reportar como encontrado</button>
        <button type="button" className="btn-eliminar">Eliminar reporte</button>
      </form>
    </div>
  );
};

export default EditarMascotaPage;
